const clientId = env.get('GOOGLE_CLIENT_ID');
if (!clientId) return fail(503, 'GOOGLE_NOT_CONFIGURED', 'ระบบยังไม่เปิดให้เข้าสู่ระบบด้วย Google');

const idToken = msg.req.body && msg.req.body.idToken;
if (typeof idToken !== 'string' || !idToken) return fail(400, 'VALIDATION_ERROR', 'ไม่พบข้อมูลจาก Google');

let client = context.get('googleClient');
if (!client) {
    const { OAuth2Client } = global.get('googleAuth');
    client = new OAuth2Client();
    context.set('googleClient', client);
}

// Only data from the verified token is trusted, never anything else the frontend sends
client.verifyIdToken({ idToken, audience: clientId }).then((ticket) => {
    const p = ticket.getPayload();
    if (!p || !p.sub || !p.email || p.email_verified !== true) {
        return fail(401, 'GOOGLE_TOKEN_INVALID', 'ไม่สามารถยืนยันบัญชี Google ได้');
    }
    msg.ctx = { googleId: p.sub, email: p.email.toLowerCase() };
    msg.topic = 'SELECT id, email, google_id, role, status FROM users WHERE google_id = ? OR email = ?';
    msg.payload = [p.sub, msg.ctx.email];
    node.send(msg);
}).catch(() => fail(401, 'GOOGLE_TOKEN_INVALID', 'ไม่สามารถยืนยันบัญชี Google ได้'));
return null;

