const { googleId, email } = msg.ctx;
const byGoogle = msg.payload.find((r) => r.google_id === googleId);
const byEmail = msg.payload.find((r) => r.email.toLowerCase() === email);
const user = byGoogle || byEmail;

if (!user) {
