function fail(status, code, message, details) {
    msg.statusCode = status;
    msg.errorCode = code;
    msg.errorMessage = message;
    if (details) msg.errorDetails = details;
    node.error(message, msg);
    return null;
}

const b = msg.payload || {};
const str = (v) => (typeof v === 'string' ? v.trim() : '');
const toId = (v) => (Number.isInteger(v) && v > 0 ? v : null);

const fullName = str(b.fullName);
if (!fullName || fullName.length > 150) return fail(400, 'VALIDATION_ERROR', 'กรุณากรอกชื่อ-นามสกุล (ไม่เกิน 150 ตัวอักษร)');

const birthDate = str(b.birthDate);
const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(birthDate);
const bd = m ? new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])) : null;
if (!bd || bd.getUTCMonth() !== +m[2] - 1 || bd.getUTCDate() !== +m[3]) {
    return fail(400, 'VALIDATION_ERROR', 'วันเกิดไม่ถูกต้อง');
}
const today = new Date(Date.now() + 7 * 3600 * 1000); // Asia/Bangkok
let age = today.getUTCFullYear() - +m[1];
if (today.getUTCMonth() + 1 < +m[2] || (today.getUTCMonth() + 1 === +m[2] && today.getUTCDate() < +m[3])) age--;
if (age < 18) return fail(400, 'UNDERAGE', 'ผู้หางานต้องมีอายุ 18 ปีขึ้นไป');
if (age > 100) return fail(400, 'VALIDATION_ERROR', 'วันเกิดไม่ถูกต้อง');

const phone = str(b.phone).replace(/[\s-]/g, '');
if (!/^0\d{8,9}$/.test(phone)) return fail(400, 'VALIDATION_ERROR', 'เบอร์โทรไม่ถูกต้อง');

const lineId = str(b.lineId);
if (lineId && !/^@?[A-Za-z0-9._-]{1,50}$/.test(lineId)) return fail(400, 'VALIDATION_ERROR', 'LINE ID ไม่ถูกต้อง');

const skills = str(b.skills);
const bio = str(b.bio);
if (skills.length > 500) return fail(400, 'VALIDATION_ERROR', 'ทักษะยาวเกิน 500 ตัวอักษร');
if (bio.length > 1000) return fail(400, 'VALIDATION_ERROR', 'แนะนำตัวยาวเกิน 1000 ตัวอักษร');

// Areas: [{ provinceId, districtId|null }]; null district = whole province (wins over its districts)
if (!Array.isArray(b.areas) || b.areas.length < 1 || b.areas.length > 30) {
    return fail(400, 'VALIDATION_ERROR', 'กรุณาเลือกพื้นที่ที่สนใจอย่างน้อย 1 แห่ง');
}
const byProvince = new Map();
for (const a of b.areas) {
    const provinceId = toId(a && a.provinceId);
    const districtId = a && a.districtId !== null && a.districtId !== undefined ? toId(a.districtId) : null;
    if (!provinceId || (a.districtId !== null && a.districtId !== undefined && !districtId)) {
        return fail(400, 'VALIDATION_ERROR', 'ข้อมูลพื้นที่ไม่ถูกต้อง');
    }
    if (!byProvince.has(provinceId)) byProvince.set(provinceId, new Set());
    byProvince.get(provinceId).add(districtId);
}
const areas = [];
for (const [provinceId, districts] of byProvince) {
    if (districts.has(null)) areas.push({ provinceId, districtId: null });
    else for (const districtId of districts) areas.push({ provinceId, districtId });
}

msg.ctx = { fullName, birthDate, phone, lineId: lineId || null, skills: skills || null, bio: bio || null, areas };
const provinceIds = [...byProvince.keys()];
const districtIds = areas.filter((a) => a.districtId).map((a) => a.districtId);
msg.topic = 'SELECT id FROM provinces WHERE id IN (?); SELECT id, province_id FROM districts WHERE id IN (?)';
msg.payload = [provinceIds, districtIds.length ? districtIds : [0]];
return msg;

// Sends a standard error response via the tab's catch node
function fail(status, code, message, details) {
    msg.statusCode = status;
    msg.errorCode = code;
    msg.errorMessage = message;
    if (details) msg.errorDetails = details;
    node.error(message, msg);
    return null;
}

const [provinceRows, districtRows] = msg.payload;
const provinces = new Set(provinceRows.map((r) => r.id));
const districtProvince = new Map(districtRows.map((r) => [r.id, r.province_id]));
const c = msg.ctx;

for (const a of c.areas) {
    if (!provinces.has(a.provinceId)) return fail(400, 'VALIDATION_ERROR', 'ไม่พบจังหวัดที่เลือก');
    if (a.districtId && districtProvince.get(a.districtId) !== a.provinceId) {
        return fail(400, 'VALIDATION_ERROR', 'อำเภอไม่อยู่ในจังหวัดที่เลือก');
    }
}

const uid = msg.user.id;
// Not a transaction: inputs are fully validated above, so the later statements cannot fail on data
msg.topic = `INSERT INTO seeker_profiles (user_id, full_name, birth_date, phone, line_id, skills, bio)
    VALUES (?, ?, ?, ?, ?, ?, ?) AS new
    ON DUPLICATE KEY UPDATE full_name = new.full_name, birth_date = new.birth_date, phone = new.phone,
        line_id = new.line_id, skills = new.skills, bio = new.bio;
DELETE FROM seeker_areas WHERE user_id = ?;
INSERT INTO seeker_areas (user_id, province_id, district_id) VALUES ?`;
msg.payload = [uid, c.fullName, c.birthDate, c.phone, c.lineId, c.skills, c.bio, uid,
    c.areas.map((a) => [uid, a.provinceId, a.districtId])];
return msg;

