function fail(status, code, message, details) {
    msg.statusCode = status;
    msg.errorCode = code;
    msg.errorMessage = message;
    if (details) msg.errorDetails = details;
    node.error(message, msg);
    return null;
}

const b = msg.payload || {};
const str = (v) => (typeof v === 'string' ? v.trim() : '');
const toId = (v) => (Number.isInteger(v) && v > 0 ? v : null);

const shopName = str(b.shopName);
if (!shopName || shopName.length > 150) return fail(400, 'VALIDATION_ERROR', 'กรุณากรอกชื่อร้าน (ไม่เกิน 150 ตัวอักษร)');
const address = str(b.address);
if (!address || address.length > 500) return fail(400, 'VALIDATION_ERROR', 'กรุณากรอกที่อยู่ร้าน (ไม่เกิน 500 ตัวอักษร)');
const provinceId = toId(b.provinceId);
const districtId = toId(b.districtId);
if (!provinceId || !districtId) return fail(400, 'VALIDATION_ERROR', 'กรุณาเลือกจังหวัดและอำเภอ');
const phone = str(b.phone).replace(/[\s-]/g, '');
if (!/^0\d{8,9}$/.test(phone)) return fail(400, 'VALIDATION_ERROR', 'เบอร์โทรไม่ถูกต้อง');
const lineId = str(b.lineId);
if (lineId && !/^@?[A-Za-z0-9._-]{1,50}$/.test(lineId)) return fail(400, 'VALIDATION_ERROR', 'LINE ID ไม่ถูกต้อง');
const description = str(b.description);
if (description.length > 2000) return fail(400, 'VALIDATION_ERROR', 'รายละเอียดร้านยาวเกิน 2000 ตัวอักษร');

msg.ctx = { shopName, address, provinceId, districtId, phone, lineId: lineId || null, description: description || null };
msg.topic = 'SELECT id FROM districts WHERE id = ? AND province_id = ?';
msg.payload = [districtId, provinceId];
return msg;

