if (!msg.payload.length) return fail(400, 'VALIDATION_ERROR', 'อำเภอไม่อยู่ในจังหวัดที่เลือก');
const c = msg.ctx;
msg.topic = `INSERT INTO shops (owner_user_id, name, description, address, province_id, district_id, phone, line_id)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?) AS new
    ON DUPLICATE KEY UPDATE name = new.name, description = new.description, address = new.address,
