const b = msg.payload || {};
if (b.acceptTerms !== true || b.acceptPdpa !== true) {
    return fail(400, 'VALIDATION_ERROR', 'กรุณายอมรับเงื่อนไขการใช้งานและนโยบายความเป็นส่วนตัว');
}
// Completes onboarding only if the role's profile exists
msg.topic = `UPDATE users u
    SET u.pdpa_accepted_at = COALESCE(u.pdpa_accepted_at, NOW()), u.profile_completed = 1
    WHERE u.id = ?
      AND ((u.role = 'seeker' AND EXISTS (SELECT 1 FROM seeker_profiles sp WHERE sp.user_id = u.id))
        OR (u.role = 'shop' AND EXISTS (SELECT 1 FROM shops s WHERE s.owner_user_id = u.id)))`;
msg.payload = [msg.user.id];
return msg;

