    msg.errorCode = code;
    msg.errorMessage = message;
    if (details) msg.errorDetails = details;
    node.error(message, msg);
    return null;
}

if (msg.sessionUser.onboardingStep !== 'done') {
    return fail(409, 'PROFILE_INCOMPLETE', 'กรุณากรอกข้อมูลโปรไฟล์ให้ครบก่อน');
}
msg.statusCode = 200;
msg.payload = { user: msg.sessionUser };
return msg;

// Sends a standard error response via the tab's catch node
function fail(status, code, message, details) {
    msg.statusCode = status;
    msg.errorCode = code;
    msg.errorMessage = message;
    if (details) msg.errorDetails = details;
    node.error(message, msg);
    return null;
}

const files = (msg.req.files || []).filter((f) => f.fieldname === 'file');
if (files.length !== 1) return fail(400, 'VALIDATION_ERROR', 'กรุณาเลือกไฟล์รูป 1 ไฟล์ (ชื่อฟิลด์ file)');
const f = files[0];
if (f.size > 5 * 1024 * 1024) return fail(413, 'FILE_TOO_LARGE', 'ไฟล์ต้องมีขนาดไม่เกิน 5 MB');

// Check the file signature, not the client-supplied mimetype / name
const buf = f.buffer;
let ext = null;
if (buf.length > 3 && buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff) ext = 'jpg';
else if (buf.length > 8 && buf.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))) ext = 'png';
if (!ext) return fail(415, 'UNSUPPORTED_FILE_TYPE', 'รองรับเฉพาะไฟล์ JPG หรือ PNG');

msg.ctx = { fileName: global.get('crypto').randomBytes(16).toString('hex') + '.' + ext, buffer: buf };
msg.topic = 'SELECT avatar_file FROM seeker_profiles WHERE user_id = ?';
msg.payload = [msg.user.id];
return msg;

