function fail(status, code, message, details) {
    msg.statusCode = status;
    msg.errorCode = code;
    msg.errorMessage = message;
    if (details) msg.errorDetails = details;
    node.error(message, msg);
    return null;
}

const row = msg.payload[0];
if (!row) return fail(409, 'PROFILE_REQUIRED', 'กรุณากรอกโปรไฟล์ก่อนอัปโหลดรูป');
msg.ctx.oldFile = row.avatar_file;
msg.filename = '/data/uploads/public/avatars/' + msg.ctx.fileName;
msg.payload = msg.ctx.buffer;
delete msg.ctx.buffer;
return msg;

msg.topic = 'UPDATE seeker_profiles SET avatar_file = ? WHERE user_id = ?';
msg.payload = [msg.ctx.fileName, msg.user.id];
return msg;

const oldFile = msg.ctx.oldFile;
msg.statusCode = 200;
msg.payload = { avatarPath: 'avatars/' + msg.ctx.fileName };
const cleanup = oldFile ? { filename: '/data/uploads/public/avatars/' + oldFile } : null;
return [msg, cleanup];

msg.topic = 'SELECT id, name_th, name_en FROM regions ORDER BY id; '
    + 'SELECT id, region_id, name_th, name_en FROM provinces ORDER BY id; '
    + 'SELECT id, province_id, name_th, name_en FROM districts ORDER BY id';
msg.payload = [];
return msg;

const [regions, provinces, districts] = msg.payload;
msg.statusCode = 200;
msg.headers = { 'Cache-Control': 'public, max-age=86400' };
msg.payload = {
    regions: regions.map((r) => ({ id: r.id, nameTh: r.name_th, nameEn: r.name_en })),
    provinces: provinces.map((p) => ({ id: p.id, regionId: p.region_id, nameTh: p.name_th, nameEn: p.name_en })),
    districts: districts.map((d) => ({ id: d.id, provinceId: d.province_id, nameTh: d.name_th, nameEn: d.name_en })),
};
return msg;

msg.topic = "SELECT DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s') AS server_time, (SELECT COUNT(*) FROM provinces) AS provinces";
msg.payload = [];
return msg;

const row = msg.payload[0];
msg.statusCode = 200;
msg.payload = { status: 'ok', database: 'connected', provinces: row.provinces, time: row.server_time };
